const input = $input.first().json;
const original = $('Escribir el mensaje acá').first().json;

return [{
  json: {
    resultado: 'Oportunidad comercial analizada correctamente',
    analysis: {
      ...input,
      channel: original.channel,
      external_message_id: original.external_message_id,
      sender_id: original.sender_id || null,
    },
    opportunity: {
      opportunity_id: 'opp-test-' + original.external_message_id,
      stage: input.sales_stage || 'nuevo',
      intent: input.intent || null,
      lead_temperature: input.lead_temperature || null,
      product_interest: input.product_interest ?? null,
      missing_information: Array.isArray(input.missing_information) ? input.missing_information : [],
      next_action: input.next_action || null,
      suggested_response: input.suggested_response || null,
    },
    persistence: {
      status: 'not_persisted',
      note: 'Workflow de prueba. La persistencia real se conecta en el flujo de ingreso de prospectos.'
    }
  }
}];
